TRAD = {}
for cid in IDS:
    TRAD[cid] = "yijing" if cid.startswith("ZY-") else "liuyao"

def basis_of(cid):
    pred,core,conf,trig,timing = C[cid]
    t = TRAD[cid]
    if t=="liuyao":
        head = "tradition: liuyao（与卡面一致）"
        sysline = "systems_used: 六爻纳甲单法（按kb-snapshot SKILL.md六爻流程与chinese-liuyao-meihua.md诸节：用神候选枚举、空墓伏决策序、动化定性裁决表、终局反转扫查、四路合参、应期三步+门类对表、R61-REV1二路复推与粒度核）；未混用他法。"
        rev = "收束复核：calibration第五节R59-REV1已标失效存档（R61起不强制），本例不执行该节、执行第六节R61-REV1；(m)指针所指条文失效状态已注明。"
        return "\n".join([head,sysline,core,timing,rev])
    else:
        head = "tradition: yijing（与卡面一致）"
        # core for ZY already contains systems line in some; keep as is (single tradition label at head)
        return "\n".join([head,core,timing])

total=0; counts=[0,0,0]
for cid in IDS:
    assert cid in C, cid
    pred,core,conf,trig,timing = C[cid]
    obj = {"case_id":cid,"prediction_text":pred,"basis":basis_of(cid),"confidence":conf,
           "trigger":{"changed_main":trig[0],"reserve_used":trig[1],"disputed":trig[2],"reason":trig[3]}}
    if TRAD[cid]!="liuyao":
        assert trig==(False,False,False,"")
    p = OUT/f"{cid}.json"
    p.write_text(json.dumps(obj,ensure_ascii=False,indent=1),encoding="utf-8")
    counts[0]+=trig[0]; counts[1]+=trig[1]; counts[2]+=trig[2]
# read-back verify (own outputs only)
for cid in IDS:
    d=json.loads((OUT/f"{cid}.json").read_text(encoding="utf-8"))
    assert d["case_id"]==cid and set(d)=={"case_id","prediction_text","basis","confidence","trigger"}
    assert set(d["trigger"])=={"changed_main","reserve_used","disputed","reason"}
    total += (OUT/f"{cid}.json").stat().st_size
print("written",len(IDS),"trigger counts changed_main/reserve_used/disputed",counts,"total_bytes",total)
